#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    /**
     * 滑動視窗 + 雜湊表
     * 時間複雜度: O(n)
     * 空間複雜度: O(min(n, m))
     */
    int lengthOfLongestSubstring(std::string s) {
        // 記錄字符最後出現的索引
        std::unordered_map<char, int> charIndex;
        int left = 0;
        int maxLength = 0;

        // right 指標遍歷字串
        for (int right = 0; right < s.length(); right++) {
            char c = s[right];

            // 如果字符已在當前視窗中
            if (charIndex.find(c) != charIndex.end() && 
                charIndex[c] >= left) {
                // 移動 left 到重複字符的下一個位置
                left = charIndex[c] + 1;
            }

            // 更新字符的索引
            charIndex[c] = right;

            // 更新最大長度
            maxLength = std::max(maxLength, right - left + 1);
        }

        return maxLength;
    }
};

